'use strict';

// MODULES //

var bench = require( '@stdlib/bench' );
var isnan = require( '@stdlib/math/base/assert/is-nan' );
var Uint32Array = require( '@stdlib/array/uint32' );
var pkg = require( './../package.json' ).name;
var xorshift128plus = require( './../lib' );


// MAIN //

bench( pkg+':factory', function benchmark( b ) {
	var rng;
	var i;

	b.tic();
	for ( i = 0; i < b.iterations; i++ ) {
		rng = xorshift128plus();
		if ( typeof rng !== 'function' ) {
			b.fail( 'should return a function' );
		}
	}
	b.toc();

	if ( isnan( rng() ) ) {
		b.fail( 'should not return NaN' );
	}
	b.pass( 'benchmark finished' );
	b.end();
});

bench( pkg+':factory:seed=<integer>', function benchmark( b ) {
	var opts;
	var rng;
	var i;

	opts = {
		'seed': 1
	};

	b.tic();
	for ( i = 0; i < b.iterations; i++ ) {
		opts.seed = i + 1;
		rng = xorshift128plus( opts );
		if ( typeof rng !== 'function' ) {
			b.fail( 'should return a function' );
		}
	}
	b.toc();

	if ( isnan( rng() ) ) {
		b.fail( 'should not return NaN' );
	}
	b.pass( 'benchmark finished' );
	b.end();
});

bench( pkg+':factory:state=<Uint32Array>', function benchmark( b ) {
	var state;
	var opts;
	var rng;
	var i;

	opts = {};
	state = new Uint32Array( 4 );
	for ( i = 0; i < state.length; i++ ) {
		state[ i ] = 123 + i;
	}
	opts.state = state;

	b.tic();
	for ( i = 0; i < b.iterations; i++ ) {
		opts.state[ 0 ] = i + 1;
		rng = xorshift128plus( opts );
		if ( typeof rng !== 'function' ) {
			b.fail( 'should return a function' );
		}
	}
	b.toc();

	if ( isnan( rng() ) ) {
		b.fail( 'should not return NaN' );
	}
	b.pass( 'benchmark finished' );
	b.end();
});

bench( pkg+':generation', function benchmark( b ) {
	var rng;
	var i;

	rng = xorshift128plus({
		'seed': 12345
	});

	b.tic();
	for ( i = 0; i < b.iterations; i++ ) {
		rng();
	}
	b.toc();
	b.pass( 'benchmark finished' );
	b.end();
});

