bench( pkg+':generation:sequential', function benchmark( b ) {
	var rng;
	var i;
	var j;

	rng = xorshift128plus({
		'seed': 55555
	});

	b.tic();
	for ( i = 0; i < b.iterations; i++ ) {
		for ( j = 0; j < 100; j++ ) {
			rng();
		}
	}
	b.toc();
	b.pass( 'benchmark finished' );
	b.end();
});

bench( pkg+':multiple:instances', function benchmark( b ) {
	var rngs;
	var i;
	var j;

	rngs = [];
	for ( i = 0; i < 100; i++ ) {
		rngs.push( xorshift128plus({
			'seed': i + 1
		}) );
	}

	b.tic();
	for ( i = 0; i < b.iterations; i++ ) {
		for ( j = 0; j < rngs.length; j++ ) {
			rngs[ j ]();
		}
	}
	b.toc();
	b.pass( 'benchmark finished' );
	b.end();
});

bench( pkg+':mixed:operations', function benchmark( b ) {
	var state;
	var rng;
	var i;

	rng = xorshift128plus({
		'seed': 66666
	});

	b.tic();
	for ( i = 0; i < b.iterations; i++ ) {
		// Generate regular value
		rng();

		// Generate normalized value
		rng.normalized();

		// Access state
		state = rng.state;
		if ( typeof state !== 'object') {
			b.fail( 'should return object' );
		}
	}
	b.toc();
	b.pass( 'benchmark finished' );
	b.end();
});

bench( pkg+':state:cycle', function benchmark( b ) {
	var state;
	var rng1;
	var rng2;
	var i;

	rng1 = xorshift128plus({
		'seed': 77777
	});
	rng2 = xorshift128plus({
		'seed': 88888
	});

	b.tic();
	for ( i = 0; i < b.iterations; i++ ) {
		// Save state from rng1
		state = rng1.state;

		// Restore state to rng2
		rng2.state = state;

		// Generate from restored PRNG
		rng2();
	}
	b.toc();
	b.pass( 'benchmark finished' );
	b.end();
});

bench( pkg+':entropy:mixing', function benchmark( b ) {
	var rng;
	var i;

	rng = xorshift128plus({
		'seed': 99999
	});

	b.tic();
	for ( i = 0; i < b.iterations; i++ ) {
		// Core generation with entropy mixing (XOR of upper/lower 32 bits)
		rng();
	}
	b.toc();
	b.pass( 'benchmark finished' );
	b.end();
});
